MARGIN = 0.08


def route(passage: Passage, neighbours: list[Labelled]) -> Routing:
    """Route a passage, or decline to.

    The margin is checked before the top label is taken. Reading `argmax` first and
    then second-guessing it reads as a confidence score bolted onto a decision that
    was already made, and it is much easier to remove by accident.
    """
    scores = tally_by_team(neighbours)
    if len(scores) < 2:
        return Routing(team=None, reason="too-few-neighbours")

    (first, first_score), (_, second_score) = scores.most_common(2)
    if first_score - second_score < MARGIN:
        return Routing(team=None, reason="ambiguous")

    return Routing(team=first, reason="nearest-neighbours")
